func reportErr(msg string, hints ...string) int {
    fmt.Fprintf(os.Stderr, "age: error: %s\n", msg)
    for _, h := range hints { fmt.Fprintf(os.Stderr, "age: hint: %s\n", h) }
    fmt.Fprintln(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report")
