}

type multiFlag []string
func (m *multiFlag) String() string { return strings.Join(*m, ",") }
func (m *multiFlag) Set(s string) error { *m = append(*m, s); return nil }

type options struct{
    encrypt bool; encryptSet bool; decrypt bool
    armor bool; pass bool; output string
    recipients multiFlag; recipFiles multiFlag; identities multiFlag; plugins multiFlag
}

type boolFlag struct{ p *bool; set *bool }
func (b boolFlag) String() string { if *b.p {return "true"}; return "false" }
func (b boolFlag) Set(s string) error { v := true; if s=="false" || s=="0" { v=false }; *b.p=v; if b.set!=nil{*b.set=true}; return nil }
func (b boolFlag) IsBoolFlag() bool { return true }

func parseArgs(args []string) (*options, []string, int) {
    var o options
    fs := flag.NewFlagSet("age", flag.ContinueOnError)
    fs.SetOutput(os.Stderr)
    fs.Usage = func(){ fmt.Fprint(os.Stderr, usageText) }
    fs.Var(boolFlag{&o.encrypt,&o.encryptSet}, "e", "")
    fs.Var(boolFlag{&o.encrypt,&o.encryptSet}, "encrypt", "")
    fs.BoolVar(&o.decrypt, "d", false, "")
    fs.BoolVar(&o.decrypt, "decrypt", false, "")
    fs.BoolVar(&o.armor, "a", false, "")
    fs.BoolVar(&o.armor, "armor", false, "")
    fs.BoolVar(&o.pass, "p", false, "")
    fs.BoolVar(&o.pass, "passphrase", false, "")
    fs.StringVar(&o.output, "o", "", "")
    fs.StringVar(&o.output, "output", "", "")
    fs.Var(&o.recipients, "r", ""); fs.Var(&o.recipients, "recipient", "")
    fs.Var(&o.recipFiles, "R", ""); fs.Var(&o.recipFiles, "recipients-file", "")
    fs.Var(&o.identities, "i", ""); fs.Var(&o.identities, "identity", "")
    fs.Var(&o.plugins, "j", "")
    help := false; fs.BoolVar(&help,"h",false,""); fs.BoolVar(&help,"help",false,"")
    ver := false; fs.BoolVar(&ver,"version",false,"")
    err := fs.Parse(args)
    if err != nil { return nil, nil, 2 }
    if help { fmt.Fprint(os.Stderr, usageText); return nil,nil,0 }
    if ver { fmt.Println(version); return nil,nil,0 }
    return &o, fs.Args(), -1
}

func main(){
    o, rest, code := parseArgs(os.Args[1:])
    if code >= 0 { os.Exit(code) }
    if len(rest) > 1 {
        os.Exit(reportErr(fmt.Sprintf("too many INPUT arguments: %q %q", rest[0], rest[1]), "only a single input file may be specified at a time"))
    }
    if o.decrypt && o.encryptSet { os.Exit(reportErr("-e/--encrypt can't be used with -d/--decrypt")) }
    decrypt := o.decrypt
    if !decrypt { o.encrypt = true }
    if decrypt {
        if len(o.recipients)>0 { os.Exit(reportErr("-r/--recipient can't be used with -d/--decrypt", "did you mean to use -i/--identity to specify a private key?")) }
        if len(o.recipFiles)>0 { os.Exit(reportErr("-R/--recipients-file can't be used with -d/--decrypt", "did you mean to use -i/--identity to specify a private key?")) }
        if o.pass { os.Exit(reportErr("-p/--passphrase can't be used with -d/--decrypt")) }
    } else {
        if len(o.identities)>0 || len(o.plugins)>0 {
            if !o.encryptSet { os.Exit(reportErr("-i/--identity and -j can't be used in encryption mode unless symmetric encryption is explicitly selected with -e/--encrypt", "did you forget to specify -d/--decrypt?")) }
        }
