        if o.pass && len(o.recipFiles)>0 { os.Exit(reportErr("-p/--passphrase can't be combined with -R/--recipients-file")) }
        if o.pass && (len(o.identities)>0 || len(o.plugins)>0) { os.Exit(reportErr("-p/--passphrase can't be combined with -i/--identity or -j")) }
    }

    var in io.Reader = os.Stdin
    var infile *os.File
    if len(rest)==1 && rest[0] != "-" {
        f, err := os.Open(rest[0]); if err != nil { os.Exit(reportErr(fmt.Sprintf("failed to open input file %q: %v", rest[0], err))) }
        defer f.Close(); infile=f; in=f
    }
    _ = infile
    var out io.Writer = os.Stdout
