        f, err := os.Create(o.output); if err != nil { os.Exit(reportErr(fmt.Sprintf("failed to open output file %q: %v", o.output, err))) }
        defer f.Close(); outf=f; out=f
    }
    _ = outf

    if decrypt {
        ids, err := readIdentities(o.identities)
        if err != nil { os.Exit(reportErr(err.Error())) }
        if err := decryptFile(in,out,ids); err != nil { os.Exit(reportErr(err.Error())) }
    } else {
        if o.pass { os.Exit(reportErr("could not read passphrase: standard input is not a terminal, and /dev/tty is not available: open /dev/tty: no such device or address")) }
        if len(o.plugins)>0 {
