// ---------- Bech32 ----------
var bechCharset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
var bechMap [128]byte
func init(){ for i:=range bechMap{bechMap[i]=255}; for i,c:=range []byte(bechCharset){bechMap[c]=byte(i)} }
func bechPolymod(vals []byte) uint32 { chk:=uint32(1); gen:=[]uint32{0x3b6a57b2,0x26508e6d,0x1ea119fa,0x3d4233dd,0x2a1462b3}; for _,v:=range vals{top:=chk>>25; chk=(chk&0x1ffffff)<<5 ^ uint32(v); for i:=0;i<5;i++{if ((top>>uint(i))&1)==1{chk^=gen[i]}}}; return chk }
func hrpExpand(hrp string) []byte { out:=make([]byte,0,len(hrp)*2+1); for i:=0;i<len(hrp);i++{out=append(out, hrp[i]>>5)}; out=append(out,0); for i:=0;i<len(hrp);i++{out=append(out, hrp[i]&31)}; return out }
func verifyChecksum(hrp string,data []byte) bool { vals:=append(hrpExpand(hrp),data...); return bechPolymod(vals)==1 }
func bechDecode(s string) (string, []byte, error){
    if s=="" {return "",nil,errors.New("empty bech32 string")}
    lower:=strings.ToLower(s); upper:=strings.ToUpper(s); if s!=lower && s!=upper {return "",nil,errors.New("mixed case bech32 string")}
    s=lower; pos:=strings.LastIndexByte(s,'1'); if pos<1 || pos+7>len(s){return "",nil,errors.New("invalid bech32 separator")}
    hrp:=s[:pos]; chars:=s[pos+1:]; data:=make([]byte,len(chars)); for i:=0;i<len(chars);i++{ch:=chars[i]; if ch>=128 || bechMap[ch]==255{return "",nil,errors.New("invalid bech32 character")}; data[i]=bechMap[ch]}
    if !verifyChecksum(hrp,data){return "",nil,errors.New("invalid checksum")}
    return hrp,data[:len(data)-6],nil
}
func convertBits(data []byte, from,to uint, pad bool)([]byte,error){ acc:=0; bits:=uint(0); maxv:=(1<<to)-1; maxacc:=(1<<(from+to-1))-1; out:=[]byte{}; for _,value:=range data{ if int(value)>>from !=0{return nil,errors.New("invalid data range")}; acc=((acc<<from)|int(value))&maxacc; bits += from; for bits>=to{ bits-=to; out=append(out,byte((acc>>bits)&maxv)) }}; if pad{ if bits>0{out=append(out,byte((acc<<(to-bits))&maxv))} } else if bits>=from || ((acc<<(to-bits))&maxv)!=0 {return nil,errors.New("invalid padding")}; return out,nil }
func decodeBechBytes(s, wantHRP string)([]byte,error){ hrp,data,err:=bechDecode(s); if err!=nil{return nil,err}; if hrp!=wantHRP{return nil,fmt.Errorf("unexpected HRP %q",hrp)}; b,err:=convertBits(data,5,8,false); if err!=nil{return nil,err}; return b,nil }

// ---------- CLI key parsing ----------
type recipient struct{ pub []byte }
type identity struct{ priv []byte; pub []byte }

func parseRecipient(s string) (*recipient,error){
    if strings.HasPrefix(s,"age1") {
        b,err:=decodeBechBytes(s,"age"); if err!=nil || len(b)!=32 { return nil,fmt.Errorf("malformed recipient %q",s) }
        return &recipient{pub:b},nil
    }
    if strings.HasPrefix(s,"ssh-") { return nil,fmt.Errorf("unsupported SSH recipient: %q", firstField(s)) }
    return nil,fmt.Errorf("unknown recipient type: %q", s)
}
func firstField(s string) string { f:=strings.Fields(s); if len(f)>0{return f[0]}; return s }
func parseIdentityLine(s string)(*identity,error){
    upper:=strings.ToUpper(s)
    if strings.HasPrefix(upper,"AGE-SECRET-KEY-1"){
        b,err:=decodeBechBytes(upper,"age-secret-key-"); if err!=nil || len(b)!=32 {return nil,fmt.Errorf("malformed secret key")}
        pk,err:=ecdh.X25519().NewPrivateKey(b); if err!=nil{return nil,fmt.Errorf("invalid secret key")}
        return &identity{priv:b,pub:pk.PublicKey().Bytes()},nil
    }
    if strings.HasPrefix(s,"-----BEGIN") || strings.HasPrefix(s,"openssh-key-v1") { return nil,fmt.Errorf("unsupported SSH identity") }
    return nil,fmt.Errorf("unknown identity type")
}
func collectRecipients(direct, files, idFiles []string)([]recipient,error){
    var out []recipient
    for _,s:=range direct{ r,err:=parseRecipient(s); if err!=nil{return nil,err}; out=append(out,*r) }
    for _,p:=range files{
        lines,err:=readLines(p); if err!=nil{return nil,fmt.Errorf("reading %q: %v",p,err)}
        for _,line:=range lines{ line=strings.TrimSpace(line); if line==""||strings.HasPrefix(line,"#"){continue}; r,err:=parseRecipient(line); if err!=nil{return nil,err}; out=append(out,*r) }
    }
    ids,err:=readIdentities(idFiles); if err!=nil{return nil,err}
    for _,id:=range ids{ out=append(out,recipient{pub:id.pub}) }
    return out,nil
}
func readLines(path string)([]string,error){
    var r io.Reader
    if path=="-" { r=os.Stdin } else { f,err:=os.Open(path); if err!=nil{return nil,fmt.Errorf("failed to open file: %v",err)}; defer f.Close(); r=f }
    sc:=bufio.NewScanner(r); var lines []string; for sc.Scan(){lines=append(lines,sc.Text())}; if err:=sc.Err(); err!=nil{return nil,err}; return lines,nil
}
func readIdentities(paths []string)([]identity,error){
    var ids []identity
    for _,p:=range paths{
        lines,err:=readLines(p); if err!=nil{return nil,fmt.Errorf("reading %q: %v",p,err)}
        for _,line:=range lines{ line=strings.TrimSpace(line); if line==""||strings.HasPrefix(line,"#"){continue}; id,err:=parseIdentityLine(line); if err!=nil{return nil,fmt.Errorf("reading %q: %v",p,err)}; ids=append(ids,*id) }
    }
    return ids,nil
}

// ---------- age format ----------
func b64(b []byte) string { return base64.RawStdEncoding.EncodeToString(b) }
func b64d(s string)([]byte,error){ return base64.RawStdEncoding.DecodeString(s) }
func hkdf(secret, salt, info []byte, n int) []byte{
    if salt==nil { salt=make([]byte,sha256.Size) }
    h:=hmac.New(sha256.New,salt); h.Write(secret); prk:=h.Sum(nil)
    var out,t []byte
    for c:=byte(1); len(out)<n; c++ { h=hmac.New(sha256.New,prk); h.Write(t); h.Write(info); h.Write([]byte{c}); t=h.Sum(nil); out=append(out,t...) }
    return out[:n]
}
func headerMAC(fileKey []byte, headerNoMAC []byte) []byte { k:=hkdf(fileKey,nil,[]byte("header"),32); h:=hmac.New(sha256.New,k); h.Write(headerNoMAC); return h.Sum(nil) }

func encryptFile(plaintext []byte, out io.Writer, recips []recipient, armor bool) error{
    fileKey:=make([]byte,16); if _,err:=rand.Read(fileKey); err!=nil{return err}
    var h bytes.Buffer
    h.WriteString("age-encryption.org/v1\n")
    for _,r:=range recips{
        st,err:=wrapX25519(fileKey,r.pub); if err!=nil{return err}
        h.Write(st)
    }
    h.WriteString("---")
    mac:=headerMAC(fileKey,h.Bytes())
    h.WriteString(" "); h.WriteString(b64(mac)); h.WriteByte('\n')
    payload:=encryptPayload(fileKey,plaintext)
    data:=append(h.Bytes(),payload...)
    if armor { data=armorEncode(data) }
    _,err:=out.Write(data); return err
}
func wrapX25519(fileKey, recipPub []byte)([]byte,error){
    ephPrivBytes:=make([]byte,32); if _,err:=rand.Read(ephPrivBytes); err!=nil{return nil,err}
    ephPriv,err:=ecdh.X25519().NewPrivateKey(ephPrivBytes); if err!=nil{return nil,err}
    peer,err:=ecdh.X25519().NewPublicKey(recipPub); if err!=nil{return nil,err}
    shared,err:=ephPriv.ECDH(peer); if err!=nil{return nil,err}
    ephPub:=ephPriv.PublicKey().Bytes()
    salt:=append(append([]byte{},ephPub...),recipPub...)
    wrapKey:=hkdf(shared,salt,[]byte("age-encryption.org/v1/X25519"),32)
    wrapped:=aeadSeal(wrapKey,make([]byte,12),fileKey,nil)
    var b bytes.Buffer
    fmt.Fprintf(&b,"-> X25519 %s\n%s\n", b64(ephPub), b64(wrapped))
    return b.Bytes(),nil
}
func encryptPayload(fileKey, plaintext []byte) []byte{
    key:=hkdf(fileKey,nil,[]byte("payload"),32)
    var out []byte
    chunks := 0
    for off:=0; ; off += 65536 {
        end:=off+65536; if end>len(plaintext){end=len(plaintext)}
        final := end==len(plaintext)
        nonce:=streamNonce(uint64(chunks),final)
        out=append(out,aeadSeal(key,nonce,plaintext[off:end],nil)...)
        chunks++
        if final { break }
    }
    return out
}
func streamNonce(counter uint64, final bool) []byte{
    n:=make([]byte,12)
    // 11-byte big-endian counter, final flag in last byte. For practical sizes this is the
    // same as zero-prefixed uint64 at bytes 3..10 plus flag byte.
    for i:=0;i<8;i++{ n[10-i]=byte(counter>>(8*uint(i))) }
    if final { n[11]=1 }
    return n
}

type stanza struct{ typ string; args []string; body []byte }
func decryptFile(in io.Reader, out io.Writer, ids []identity) error{
    data,err:=io.ReadAll(in); if err!=nil{return fmt.Errorf("failed to read input: %v",err)}
    if bytes.HasPrefix(data,[]byte("-----BEGIN AGE ENCRYPTED FILE-----")) || bytes.HasPrefix(bytes.TrimLeft(data,"\r\n\t "),[]byte("-----BEGIN AGE ENCRYPTED FILE-----")){
        data,err=armorDecode(data); if err!=nil{return err}
    }
    fileKey, payload, err := parseAndUnwrap(data, ids)
    if err!=nil{return err}
    pt,err:=decryptPayload(fileKey,payload); if err!=nil{return err}
    _,err=out.Write(pt); return err
}
func parseAndUnwrap(data []byte, ids []identity)([]byte,[]byte,error){
    if len(data)==0 { return nil,nil,fmt.Errorf("failed to read header: parsing age header: file is empty") }
    rd:=bufio.NewReader(bytes.NewReader(data))
    first,err:=rd.ReadString('\n'); if err!=nil { return nil,nil,fmt.Errorf("failed to read header: parsing age header: unexpected EOF") }
    headerNoMac:=[]byte(first)
    if strings.TrimRight(first,"\n")!="age-encryption.org/v1" { return nil,nil,fmt.Errorf("failed to read header: parsing age header: invalid version line") }
    var stanzas []stanza
    for {
        line,err:=rd.ReadString('\n'); if err!=nil { return nil,nil,fmt.Errorf("failed to read header: parsing age header: unexpected EOF") }
        lineTrim:=strings.TrimSuffix(line,"\n")
        if strings.HasPrefix(lineTrim,"---"){
            if !strings.HasPrefix(lineTrim,"--- ") { return nil,nil,fmt.Errorf("failed to read header: parsing age header: malformed closing line") }
            macB64:=strings.TrimPrefix(lineTrim,"--- ")
            mac,err:=b64d(macB64); if err!=nil || len(mac)!=32 { return nil,nil,fmt.Errorf("failed to read header: parsing age header: invalid header MAC") }
            headerNoMac=append(headerNoMac,[]byte("---")...)
            remaining, _ := io.ReadAll(rd)
            for _,fk:=range tryUnwrap(stanzas,ids){
                if hmac.Equal(headerMAC(fk,headerNoMac),mac){ return fk,remaining,nil }
            }
            if len(ids)==0 { return nil,nil,fmt.Errorf("no identity matched any of the recipients") }
            return nil,nil,fmt.Errorf("no identity matched any of the recipients")
        }
        headerNoMac=append(headerNoMac,[]byte(line)...)
        if !strings.HasPrefix(lineTrim,"-> ") { return nil,nil,fmt.Errorf("failed to read header: parsing age header: malformed stanza") }
        fields:=strings.Fields(lineTrim)
        if len(fields)<2 { return nil,nil,fmt.Errorf("failed to read header: parsing age header: malformed stanza") }
        typ:=fields[1]; args:=fields[2:]
        bodyLine,err:=rd.ReadString('\n'); if err!=nil { return nil,nil,fmt.Errorf("failed to read header: parsing age header: unexpected EOF") }
        headerNoMac=append(headerNoMac,[]byte(bodyLine)...)
        bodyLine=strings.TrimSuffix(bodyLine,"\n")
        body,err:=b64d(bodyLine); if err!=nil { return nil,nil,fmt.Errorf("failed to read header: parsing age header: invalid stanza body") }
        stanzas=append(stanzas,stanza{typ:typ,args:args,body:body})
    }
}
func tryUnwrap(stanzas []stanza, ids []identity) [][]byte{
    var out [][]byte
    for _,st:=range stanzas{
        if st.typ!="X25519" || len(st.args)!=1 || len(st.body)!=32 { continue }
        ephPub,err:=b64d(st.args[0]); if err!=nil || len(ephPub)!=32 { continue }
        for _,id:=range ids{
            fk,err:=unwrapX25519(st.body,ephPub,id); if err==nil { out=append(out,fk) }
        }
    }
    return out
}
func unwrapX25519(wrapped,ephPub []byte,id identity)([]byte,error){
    priv,err:=ecdh.X25519().NewPrivateKey(id.priv); if err!=nil{return nil,err}
    peer,err:=ecdh.X25519().NewPublicKey(ephPub); if err!=nil{return nil,err}
    shared,err:=priv.ECDH(peer); if err!=nil{return nil,err}
    salt:=append(append([]byte{},ephPub...),id.pub...)
    key:=hkdf(shared,salt,[]byte("age-encryption.org/v1/X25519"),32)
    return aeadOpen(key,make([]byte,12),wrapped,nil)
}
func decryptPayload(fileKey,payload []byte)([]byte,error){
    key:=hkdf(fileKey,nil,[]byte("payload"),32)
    var out []byte; counter:=uint64(0)
    for len(payload)>0{
        if len(payload)<16 { return nil,fmt.Errorf("failed to decrypt and authenticate payload chunk: %v", "message authentication failed") }
        take:=65536+16; final:=false
        if len(payload) <= take { take=len(payload); final=true }
        chunk:=payload[:take]; payload=payload[take:]
        pt,err:=aeadOpen(key,streamNonce(counter,final),chunk,nil); if err!=nil { return nil,fmt.Errorf("failed to decrypt and authenticate payload chunk: %v",err) }
        out=append(out,pt...); counter++
        if final { if len(payload)!=0{return nil,fmt.Errorf("trailing data after final payload chunk")}; break }
    }
    if counter==0 { return nil,fmt.Errorf("missing payload") }
    return out,nil
}

// ---------- Armor ----------
func armorEncode(data []byte) []byte{
    enc:=base64.StdEncoding.EncodeToString(data)
    var b bytes.Buffer
    b.WriteString("-----BEGIN AGE ENCRYPTED FILE-----\n")
    for len(enc)>64 { b.WriteString(enc[:64]); b.WriteByte('\n'); enc=enc[64:] }
    if len(enc)>0 { b.WriteString(enc); b.WriteByte('\n') }
    b.WriteString("-----END AGE ENCRYPTED FILE-----\n")
    return b.Bytes()
}
func armorDecode(data []byte)([]byte,error){
    s:=strings.TrimSpace(string(data))
    const begin="-----BEGIN AGE ENCRYPTED FILE-----"
    const end="-----END AGE ENCRYPTED FILE-----"
    if !strings.HasPrefix(s,begin){return nil,fmt.Errorf("failed to read header: parsing age header: invalid armor")}
    s=strings.TrimPrefix(s,begin); s=strings.TrimLeft(s,"\r\n")
    if !strings.HasSuffix(s,end){return nil,fmt.Errorf("failed to read header: parsing age header: invalid armor")}
    s=strings.TrimSuffix(s,end); s=strings.TrimSpace(s)
    s=strings.ReplaceAll(s,"\n",""); s=strings.ReplaceAll(s,"\r","")
    b,err:=base64.StdEncoding.DecodeString(s); if err!=nil{return nil,fmt.Errorf("failed to decode armor: %v",err)}
    return b,nil
}

// ---------- ChaCha20-Poly1305 ----------
func quarter(x *[16]uint32,a,b,c,d int){ x[a]+=x[b]; x[d]^=x[a]; x[d]=(x[d]<<16)|(x[d]>>16); x[c]+=x[d]; x[b]^=x[c]; x[b]=(x[b]<<12)|(x[b]>>20); x[a]+=x[b]; x[d]^=x[a]; x[d]=(x[d]<<8)|(x[d]>>24); x[c]+=x[d]; x[b]^=x[c]; x[b]=(x[b]<<7)|(x[b]>>25) }
func chachaBlock(key []byte, counter uint32, nonce []byte) [64]byte{
    var st [16]uint32
    st[0]=0x61707865; st[1]=0x3320646e; st[2]=0x79622d32; st[3]=0x6b206574
    for i:=0;i<8;i++{st[4+i]=binary.LittleEndian.Uint32(key[i*4:])}
    st[12]=counter; st[13]=binary.LittleEndian.Uint32(nonce[0:4]); st[14]=binary.LittleEndian.Uint32(nonce[4:8]); st[15]=binary.LittleEndian.Uint32(nonce[8:12])
    x:=st
    for i:=0;i<10;i++{ quarter(&x,0,4,8,12); quarter(&x,1,5,9,13); quarter(&x,2,6,10,14); quarter(&x,3,7,11,15); quarter(&x,0,5,10,15); quarter(&x,1,6,11,12); quarter(&x,2,7,8,13); quarter(&x,3,4,9,14) }
    var out [64]byte; for i:=0;i<16;i++{binary.LittleEndian.PutUint32(out[i*4:],x[i]+st[i])}; return out
}
func chachaXOR(key,nonce,in []byte, counter uint32) []byte{ out:=make([]byte,len(in)); for off:=0; off<len(in); off+=64{ block:=chachaBlock(key,counter,nonce); counter++; n:=64; if len(in)-off<n{n=len(in)-off}; for i:=0;i<n;i++{out[off+i]=in[off+i]^block[i]} }; return out }
func pad16Len(n int) int { if n%16==0{return 0}; return 16-n%16 }
func poly1305MAC(polyKey, aad, ct []byte) []byte{
    msg:=make([]byte,0,len(aad)+len(ct)+64)
    msg=append(msg,aad...); msg=append(msg,make([]byte,pad16Len(len(aad)))...)
    msg=append(msg,ct...); msg=append(msg,make([]byte,pad16Len(len(ct)))...)
    var lens [16]byte; binary.LittleEndian.PutUint64(lens[0:8],uint64(len(aad))); binary.LittleEndian.PutUint64(lens[8:16],uint64(len(ct))); msg=append(msg,lens[:]...)
    rBytes:=append([]byte{},polyKey[:16]...)
    rBytes[3]&=15; rBytes[7]&=15; rBytes[11]&=15; rBytes[15]&=15; rBytes[4]&=252; rBytes[8]&=252; rBytes[12]&=252
    r:=leBig(rBytes); s:=leBig(polyKey[16:32]); p:=new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1),130),big.NewInt(5)); acc:=big.NewInt(0)
    for off:=0; off<len(msg); off+=16{ end:=off+16; if end>len(msg){end=len(msg)}; block:=msg[off:end]; nBytes:=append([]byte{},block...); nBytes=append(nBytes,1); n:=leBig(nBytes); acc.Add(acc,n); acc.Mul(acc,r); acc.Mod(acc,p) }
    acc.Add(acc,s); mod:=new(big.Int).Lsh(big.NewInt(1),128); acc.Mod(acc,mod)
    return bigToLE(acc,16)
}
func leBig(b []byte)*big.Int{ rev:=make([]byte,len(b)); for i:=range b{rev[len(b)-1-i]=b[i]}; return new(big.Int).SetBytes(rev) }
func bigToLE(x *big.Int,n int)[]byte{ be:=x.Bytes(); out:=make([]byte,n); for i:=0;i<len(be)&&i<n;i++{out[i]=be[len(be)-1-i]}; return out }
func aeadSeal(key,nonce,pt,aad []byte) []byte{ block0:=chachaBlock(key,0,nonce); polyKey:=block0[:32]; ct:=chachaXOR(key,nonce,pt,1); tag:=poly1305MAC(polyKey,aad,ct); return append(ct,tag...) }
func aeadOpen(key,nonce,ctTag,aad []byte)([]byte,error){ if len(ctTag)<16{return nil,errors.New("message authentication failed")}; ct:=ctTag[:len(ctTag)-16]; tag:=ctTag[len(ctTag)-16:]; block0:=chachaBlock(key,0,nonce); exp:=poly1305MAC(block0[:32],aad,ct); if !hmac.Equal(tag,exp){return nil,errors.New("message authentication failed")}; return chachaXOR(key,nonce,ct,1),nil }

