// ---------- SSH Ed25519 helpers ----------
func readSSHString(b []byte, off *int) ([]byte, error) {
	if *off+4 > len(b) {
		return nil, io.ErrUnexpectedEOF
	}
	n := int(binary.BigEndian.Uint32(b[*off : *off+4]))
	*off += 4
	if n < 0 || *off+n > len(b) {
		return nil, io.ErrUnexpectedEOF
	}
	v := b[*off : *off+n]
	*off += n
	return v, nil
}

func parseSSHEd25519Public(line string) ([]byte, []byte, error) {
	f := strings.Fields(line)
	if len(f) < 2 || f[0] != "ssh-ed25519" {
		return nil, nil, fmt.Errorf("invalid public key")
	}
	wire, err := base64.StdEncoding.DecodeString(f[1])
	if err != nil {
		return nil, nil, err
	}
	off := 0
	typ, err := readSSHString(wire, &off)
	if err != nil || string(typ) != "ssh-ed25519" {
		return nil, nil, fmt.Errorf("invalid public key")
	}
	pub, err := readSSHString(wire, &off)
	if err != nil || len(pub) != 32 {
		return nil, nil, fmt.Errorf("invalid public key")
	}
	return pub, wire, nil
}

func ed25519PubToX25519(pub []byte) ([]byte, error) {
	if len(pub) != 32 {
		return nil, fmt.Errorf("invalid Ed25519 public key")
	}
	p := new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), 255), big.NewInt(19))
	yBytes := append([]byte{}, pub...)
	yBytes[31] &= 0x7f
	y := leBig(yBytes)
	one := big.NewInt(1)
	num := new(big.Int).Add(one, y)
	num.Mod(num, p)
	den := new(big.Int).Sub(one, y)
	den.Mod(den, p)
	inv := new(big.Int).ModInverse(den, p)
	if inv == nil {
		return nil, fmt.Errorf("invalid Ed25519 public key")
	}
	u := new(big.Int).Mul(num, inv)
	u.Mod(u, p)
	return bigToLE(u, 32), nil
}

func parseOpenSSHEd25519Private(pemText string) (*identity, error) {
	const begin = "-----BEGIN OPENSSH PRIVATE KEY-----"
	const end = "-----END OPENSSH PRIVATE KEY-----"
	s := strings.TrimSpace(pemText)
	if !strings.HasPrefix(s, begin) || !strings.HasSuffix(s, end) {
		return nil, fmt.Errorf("unknown identity type")
	}
	s = strings.TrimPrefix(s, begin)
	s = strings.TrimSuffix(s, end)
	s = strings.ReplaceAll(s, "\n", "")
	s = strings.ReplaceAll(s, "\r", "")
	raw, err := base64.StdEncoding.DecodeString(strings.TrimSpace(s))
	if err != nil {
		return nil, err
	}
	magic := []byte("openssh-key-v1\x00")
	if !bytes.HasPrefix(raw, magic) {
		return nil, fmt.Errorf("unsupported SSH identity")
	}
	off := len(magic)
	cipher, err := readSSHString(raw, &off); if err != nil { return nil, err }
